249	#[derive(Debug, PartialEq, Eq, Clone)]
250	enum ParseState<'a> {
251	    /// Parsing a value done, there is no state to record.
252	    ValueDone,
253	
254	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
255	    Pos((usize, usize)),
256	
257	    /// Parsing a optional flag argument
258	    Opt(OptState<'a>),
259	}
260	
261	/// State kept while the values of an option are still being parsed.
262	#[derive(Debug, PartialEq, Eq, Clone)]
263	struct OptState<'a> {
264	    opt: &'a clap::Arg,
265	    /// Shell-word values consumed, counted the way the parser does so that
266	    /// [`ArgValueCompleter::complete_at`] keeps indexing shell arguments
267	    /// rather than delimiter-separated fragments.
268	    words: usize,
269	    /// Canonical possible-value names of the valid, committed fragments of
270	    /// the current occurrence. Only populated for strict delimited groups.
271	    used: Vec<String>,
272	    /// Whether the most recent shell word ended with the value delimiter, so
273	    /// the word under the cursor is still filling this group (and may not
274	    /// switch scope no matter how it is shaped).
275	    open: bool,
276	    /// Whether a committed fragment of the current group was invalid (empty,
277	    /// unknown, duplicated, or past the group's capacity). Such a group stays
278	    /// locked on value completion and never yields candidates or lets a later
279	    /// word switch scope.
280	    invalid: bool,
281	}
282	
283	impl<'a> OptState<'a> {
284	    fn new(opt: &'a clap::Arg) -> Self {
285	        Self {
286	            opt,
287	            words: 0,
288	            used: Vec::new(),
289	            open: false,
290	            invalid: false,
291	        }
292	    }
293	
294	    fn is_strict_group(&self) -> bool {
295	        is_strict_group_arg(self.opt)
296	    }
297	
298	    /// Maximum number of values the option accepts; for strict delimited
299	    /// groups this is the number of fragments allowed in one occurrence.
300	    fn capacity(&self) -> usize {
301	        self.opt.get_num_args().expect("built").max_values()
302	    }
303	
304	    /// Record a shell word as a value of this option.
305	    ///
306	    /// `attached` marks a value glued to its flag (`--opt=a,b`). For options
307	    /// whose delimiter is not a strict group, such a word counts every
308	    /// delimiter-separated fragment toward the value range; a space-separated
309	    /// word counts once. For strict groups the fragments are instead validated
310	    /// into `used`, except the empty slot still being typed after a trailing
311	    /// delimiter.
312	    fn observe(&mut self, word: &OsStr, attached: bool) {
313	        if !self.is_strict_group() {
314	            let count = if attached {
315	                attached_value_count(self.opt, word)
316	            } else {
317	                1
318	            };
319	            self.words += count;
320	            return;
321	        }
322	
323	        self.words += 1;
324	        if self.invalid {
325	            return;
326	        }
327	        let delimiter = self.opt.get_value_delimiter().expect("strict group");
328	        let capacity = self.capacity();
329	        self.open = word.to_string_lossy().ends_with(delimiter);
330	        let Some(word) = word.to_str() else {
331	            self.invalid = true;
332	            return;
333	        };
334	        let mut fragments = word.split(delimiter);
335	        if self.open {
336	            // A trailing delimiter opens the slot still being typed, so its
337	            // empty fragment is not a committed value.
338	            fragments.next_back();
339	        }
340	        for fragment in fragments {
341	            if self.used.len() >= capacity {
342	                self.invalid = true;
343	                break;
344	            }
345	            match canonical_possible_value(self.opt, fragment) {
346	                Some(name) if !self.used.contains(&name) => self.used.push(name),
347	                _ => {
348	                    // Empty (also a doubled delimiter), unknown, or duplicated
349	                    // fragment: the parser would reject this group.
350	                    self.invalid = true;
351	                    break;
352	                }
353	            }
354	        }
355	    }
356	
357	    /// Consume a value and return the state parsing should resume with.
358	    ///
359	    /// The delimiter separates several fragments within one shell word, so a
360	    /// word that does not end with the delimiter is a complete value group and
361	    /// ordinary parsing resumes on the next word. A trailing delimiter instead
362	    /// opens a fragment still being typed, and an invalid committed fragment
363	    /// cannot be salvaged; both keep the group locked on values. An empty
364	    /// attached value (`--opt=`) leaves the option waiting for its first value.
365	    fn finish(self) -> ParseState<'a> {
366	        if self.is_strict_group() {
367	            if self.words == 0 || self.invalid || self.open {
368	                ParseState::Opt(self)
369	            } else {
370	                ParseState::ValueDone
371	            }
372	        } else if self.words >= self.capacity() {
373	            ParseState::ValueDone
374	        } else {
375	            ParseState::Opt(self)
376	        }
377	    }
378	}
379	
380	/// Whether an option's values form a delimited group that can hold more than
381	/// one fragment and whose fragments are validated while typed.
382	///
383	/// Single-value options (a maximum of one) are excluded: their delimiter only
384	/// joins several suggestions into one word, so completed fragments are not
385	/// validated against each other.
386	fn is_strict_group_arg(arg: &clap::Arg) -> bool {
387	    arg.get_value_delimiter().is_some()
388	        && arg.get_num_args().expect("built").max_values() > 1
389	        && possible_values(arg).is_some()
390	}
391	
392	/// The canonical possible-value name for `fragment`, honoring aliases and the
393	/// argument's case-insensitivity, or `None` when it is not a legal value.
394	fn canonical_possible_value(arg: &clap::Arg, fragment: &str) -> Option<String> {
395	    let ignore_case = arg.is_ignore_case_set();
396	    possible_values(arg)?
397	        .find(|value| value.matches(fragment, ignore_case))
398	        .map(|value| value.get_name().to_owned())
399	}
400	
401	/// Complete the word under the cursor for a strict delimited group.
402	///
403	/// Fragments already committed in earlier shell words are read from `state`;
404	/// fragments committed within the word under the cursor are validated here.
405	/// The fragment still being typed is matched against the possible values, and
406	/// every suggestion keeps the typed prefix (prior fragments and delimiters).
407	/// Any empty, unknown, duplicated, or over-capacity fragment yields an empty
408	/// result.
409	fn complete_strict_group(cursor: &str, state: &OptState<'_>) -> Vec<CompletionCandidate> {
410	    debug!(
411	        "complete_strict_group: arg={:?}, cursor={cursor:?}, used={:?}, invalid={}",
412	        state.opt.get_id(),
413	        state.used,
414	        state.invalid
415	    );
416	    if state.invalid {
417	        return Vec::new();
418	    }
419	    let delimiter = state.opt.get_value_delimiter().expect("strict group");
420	    let capacity = state.capacity();
421	
422	    let ends_with_delimiter = cursor.ends_with(delimiter);
423	    let mut parts = cursor.split(delimiter);
424	    let typed = if ends_with_delimiter {
425	        // The cursor sits right after a delimiter: the trailing empty element
426	        // is the fresh fragment being typed, not a committed value.
427	        parts.next_back();
428	        ""
429	    } else {
430	        parts.next_back().unwrap_or("")
431	    };
432	
433	    let mut used = state.used.clone();
434	    for fragment in parts {
435	        if used.len() >= capacity {
436	            return Vec::new();
437	        }
438	        match canonical_possible_value(state.opt, fragment) {
439	            Some(name) if !used.contains(&name) => used.push(name),
440	            _ => return Vec::new(),
441	        }
442	    }
443	
444	    if used.len() >= capacity {
445	        // Every slot is taken; there is no room for another fragment.
446	        return Vec::new();
447	    }
448	
449	    // Retain the text typed before the current fragment, including the last
450	    // delimiter, so suggestions replace only the fragment under the cursor.
451	    let prefix = cursor
452	        .rfind(delimiter)
453	        .map(|pos| cursor[..pos + delimiter.len_utf8()].to_owned());
454	
455	    let possible = possible_values(state.opt).expect("strict group");
456	    let mut values = complete_candidates_str(typed, possible_value_candidates(possible));
457	    // A value already committed to the group cannot be repeated.
458	    values.retain(|candidate| {
459	        candidate
460	            .get_value()
461	            .to_str()
462	            .is_none_or(|name| !used.iter().any(|used| used == name))
463	    });
464	
465	    if let Some(prefix) = prefix {
466	        values = values
467	            .into_iter()
468	            .map(|comp| comp.add_prefix(prefix.clone()))
469	            .collect();
470	    }
471	    values = values
472	        .into_iter()
473	        .map(|comp| {
474	            if comp.get_tag().is_some() {
475	                comp
476	            } else {
477	                comp.tag(Some(state.opt.to_string().into()))
478	            }
479	        })
480	        .collect();
481	
482	    values
483	}
484	
485	fn complete_arg(
486	    arg: &clap_lex::ParsedArg<'_>,
487	    cmd: &clap::Command,
488	    current_dir: Option<&std::path::Path>,
489	    pos_index: usize,
490	    is_escaped: bool,
491	    state: ParseState<'_>,
492	    used_args: &[clap::Id],
493	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
494	    debug!(
495	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
496	        arg,
497	        cmd.get_name(),
498	        current_dir,
499	        pos_index,
500	        state
501	    );
502	    let mut completions = Vec::<CompletionCandidate>::new();
503	
504	    match state {
505	        ParseState::ValueDone => {
506	            if !is_escaped {
507	                if let Ok(value) = arg.to_value() {
508	                    completions.extend(complete_subcommand(value, cmd));
509	                }
510	            }
511	
512	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
513	                completions.extend(complete_arg_value(
514	                    arg.to_value(),
515	                    positional,
516	                    current_dir,
517	                    0,
518	                ));
519	            }
520	            if !is_escaped {
521	                completions.extend(complete_option(arg, cmd, current_dir));
522	            }
523	        }
524	        ParseState::Pos((_, num_arg)) => {
525	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
526	                completions.extend(complete_arg_value(
527	                    arg.to_value(),
528	                    positional,
529	                    current_dir,
530	                    num_arg.saturating_sub(1),
531	                ));
532	                if !is_escaped
533	                    && positional
534	                        .get_num_args()
535	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
536	                {
537	                    completions.extend(complete_option(arg, cmd, current_dir));
538	                }
539	            }
540	        }
541	        ParseState::Opt(state) => {
542	            if state.is_strict_group() {
543	                // Every word belongs to the pending delimited group until it is
544	                // complete; it is never an option, positional, or subcommand.
545	                if let Ok(cursor) = arg.to_value() {
546	                    completions.extend(complete_strict_group(cursor, &state));
547	                }
548	            } else {
549	                let opt = state.opt;
550	                // `words` counts already-consumed values; the word under the
551	                // cursor is the next one, so the option sees one more value.
552	                let count = state.words + 1;
553	                completions.extend(complete_arg_value(
554	                    arg.to_value(),
555	                    opt,
556	                    current_dir,
557	                    count.saturating_sub(1),
558	                ));
559	                let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
560	                if count > min && can_switch_to_other_arg(opt, arg) {
561	                    // The option's required values are satisfied and this word
562	                    // would be parsed as a new flag rather than another value, so
563	                    // also complete it as a positional, flag, option or subcommand.
564	                    completions.extend(complete_arg(
565	                        arg,
566	                        cmd,
567	                        current_dir,
568	                        pos_index,
569	                        is_escaped,
570	                        ParseState::ValueDone,
571	                        used_args,
572	                    )?);
573	                }
574	            }
575	        }
576	    }
577	    filter_unavailable_args(&mut completions, cmd, used_args);
578	    if completions.iter().any(|a| !a.is_hide_set()) {
579	        completions.retain(|a| !a.is_hide_set());
580	    }
581	    dedup_argument_candidates(&mut completions, arg.is_empty());
582	
583	    let mut tags = Vec::new();
584	    for candidate in &completions {
585	        let tag = candidate.get_tag().cloned();
586	        if !tags.contains(&tag) {
587	            tags.push(tag);
588	        }
589	    }
590	    completions.sort_by_key(|c| {
591	        (
592	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
593	            c.get_display_order(),
594	        )
595	    });
596	
597	    Ok(completions)
598	}
599	
600	fn complete_option(
601	    arg: &clap_lex::ParsedArg<'_>,
602	    cmd: &clap::Command,
603	    current_dir: Option<&std::path::Path>,
604	) -> Vec<CompletionCandidate> {
605	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
606	    let mut completions = Vec::<CompletionCandidate>::new();
607	    if arg.is_empty() {
608	        completions.extend(longs_and_visible_aliases(cmd));
609	        completions.extend(hidden_longs_aliases(cmd));
610	
611	        let dash_or_arg = if arg.is_empty() {
612	            "-".into()
613	        } else {
614	            arg.to_value_os().to_string_lossy()
615	        };
616	        completions.extend(
617	            shorts_and_visible_aliases(cmd)
618	                .into_iter()
619	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
620	        );
621	    } else if arg.is_stdio() {
622	        // HACK: Assuming knowledge of is_stdio
623	        let dash_or_arg = if arg.is_empty() {
624	            "-".into()
625	        } else {
626	            arg.to_value_os().to_string_lossy()
627	        };
628	        completions.extend(
629	            shorts_and_visible_aliases(cmd)
630	                .into_iter()
631	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
632	        );
633	
634	        completions.extend(longs_and_visible_aliases(cmd));
635	        completions.extend(hidden_longs_aliases(cmd));
636	    } else if arg.is_escape() {
637	        // HACK: Assuming knowledge of is_escape
638	        completions.extend(longs_and_visible_aliases(cmd));
639	        completions.extend(hidden_longs_aliases(cmd));
640	    } else if let Some((flag, value)) = arg.to_long() {
641	        if let Ok(flag) = flag {
642	            if let Some(value) = value {
643	                if let Some(arg) = cmd.get_arguments().find(|a| is_long_match(a, flag)) {
644	                    if is_strict_group_arg(arg) {
645	                        // The whole attached word is the delimited group being
646	                        // typed, so its committed fragments are validated in
647	                        // place and only the fragment after the last delimiter
648	                        // is offered; the flag spelling is re-prefixed below.
649	                        if let Some(value) = value.to_str() {
650	                            let state = OptState::new(arg);
651	                            completions.extend(
652	                                complete_strict_group(value, &state)
653	                                    .into_iter()
654	                                    .map(|comp| comp.add_prefix(format!("--{flag}="))),
655	                            );
656	                        }
657	                    } else {
658	                        completions.extend(
659	                            complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
660	                                .into_iter()
661	                                .map(|comp| comp.add_prefix(format!("--{flag}="))),
662	                        );
663	                    }
664	                }
665	            } else {
666	                completions.extend(
667	                    longs_and_visible_aliases(cmd)
668	                        .into_iter()
669	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
670	                );
671	                completions.extend(
672	                    hidden_longs_aliases(cmd)
673	                        .into_iter()
674	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
675	                );
676	            }
677	        }
678	    } else if let Some(short) = arg.to_short() {
679	        if !short.is_negative_number() {
680	            // Find the first takes_values option.
681	            let (leading_flags, _, takes_value_opt, mut short) = parse_shortflags(cmd, short);
682	
683	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
684	            if let Some(opt) = takes_value_opt {
685	                let mut peek_short = short.clone();
686	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
687	                    short.next_flag();
688	                    true
689	                } else {
690	                    false
691	                };
692	
693	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
694	                let group_completions = if is_strict_group_arg(opt) {
695	                    value
696	                        .to_str()
697	                        .map(|value| complete_strict_group(value, &OptState::new(opt)))
698	                        .unwrap_or_default()
699	                } else {
700	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
701	                };
702	                completions.extend(group_completions.into_iter().map(|comp| {
703	                    let sep = if has_equal { "=" } else { "" };
704	                    comp.add_prefix(format!("-{leading_flags}{sep}"))
705	                }));
706	            } else {
707	                completions.extend(
708	                    shorts_and_visible_aliases(cmd)
709	                        .into_iter()
710	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
711	                );
712	            }
713	        }
714	    }
715	    debug!("complete_option: completions={completions:?}");
716	    completions
717	}
