719	fn complete_arg_value(
720	    value: Result<&str, &OsStr>,
721	    arg: &clap::Arg,
722	    current_dir: Option<&std::path::Path>,
723	    arg_index: usize,
724	) -> Vec<CompletionCandidate> {
725	    let mut values = Vec::new();
726	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
727	
728	    let (prefix, value) =
729	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
730	
731	    let value_os = match value {
732	        Ok(value) => OsStr::new(value),
733	        Err(value_os) => value_os,
734	    };
735	
736	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
737	        values.extend(completer.complete_at(arg_index, value_os));
738	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
739	        values.extend(complete_value_candidates(
740	            value_os,
741	            completer.value_candidates(),
742	        ));
743	    } else if let Some(possible_values) = possible_values(arg) {
744	        if let Ok(value) = value {
745	            values.extend(complete_candidates_str(
746	                value,
747	                possible_value_candidates(possible_values),
748	            ));
749	        }
750	    } else {
751	        match arg.get_value_hint() {
752	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
753	                // Should not complete
754	            }
755	            clap::ValueHint::AnyPath => {
756	                values.extend(complete_path(value_os, current_dir, &|_| true));
757	            }
758	            clap::ValueHint::FilePath => {
759	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
760	            }
761	            clap::ValueHint::DirPath => {
762	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
763	            }
764	            clap::ValueHint::ExecutablePath => {
765	                use is_executable::IsExecutable;
766	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
767	            }
768	            clap::ValueHint::CommandName
769	            | clap::ValueHint::CommandString
770	            | clap::ValueHint::CommandWithArguments
771	            | clap::ValueHint::Username
772	            | clap::ValueHint::Hostname
773	            | clap::ValueHint::Url
774	            | clap::ValueHint::EmailAddress => {
775	                // No completion implementation
776	            }
777	            _ => {
778	                // Safe-ish fallback
779	                values.extend(complete_path(value_os, current_dir, &|_| true));
780	            }
781	        }
782	
783	        values.sort();
784	    }
785	
786	    if let Some(prefix) = prefix {
787	        values = values
788	            .into_iter()
789	            .map(|comp| comp.add_prefix(prefix))
790	            .collect();
791	    }
792	    values = values
793	        .into_iter()
794	        .map(|comp| {
795	            if comp.get_tag().is_some() {
796	                comp
797	            } else {
798	                comp.tag(Some(arg.to_string().into()))
799	            }
800	        })
801	        .collect();
802	
803	    debug!("complete_arg_value: values={values:?}");
804	    values
805	}
