807	fn rsplit_delimiter<'s, 'o>(
808	    value: Result<&'s str, &'o OsStr>,
809	    delimiter: Option<char>,
810	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
811	    let delimiter = delimiter?;
812	    let value = value.ok()?;
813	    let pos = value.rfind(delimiter)?;
814	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
815	    Some((Some(prefix), Ok(value)))
816	}
