990	/// Parse the short flags and find the first `takes_values` option.
991	///
992	/// Returns the raw leading flags, every matched argument, the first
993	/// `takes_values` option (if any), and the remaining unparsed flags.
994	fn parse_shortflags<'c, 's>(
995	    cmd: &'c clap::Command,
996	    mut short: clap_lex::ShortFlags<'s>,
997	) -> (
998	    String,
999	    Vec<&'c clap::Arg>,
1000	    Option<&'c clap::Arg>,
1001	    clap_lex::ShortFlags<'s>,
1002	) {
1003	    let takes_value_opt;
1004	    let mut matched_opts = Vec::new();
1005	    let mut leading_flags = String::new();
1006	    // Find the first takes_values option.
1007	    loop {
1008	        match short.next_flag() {
1009	            Some(Ok(opt)) => {
1010	                leading_flags.push(opt);
1011	                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
1012	                if let Some(opt) = opt {
1013	                    matched_opts.push(opt);
1014	                }
1015	                if opt
1016	                    .map(|o| o.get_num_args().expect("built").takes_values())
1017	                    .unwrap_or(false)
1018	                {
1019	                    takes_value_opt = opt;
1020	                    break;
1021	                }
1022	            }
1023	            Some(Err(_)) | None => {
1024	                takes_value_opt = None;
1025	                break;
1026	            }
1027	        }
1028	    }
1029	
1030	    (leading_flags, matched_opts, takes_value_opt, short)
1031	}
