1042	/// Whether the argument can be addressed by the short flag `flag`,
1043	/// including visible and hidden aliases.
1044	fn is_short_match(arg: &clap::Arg, flag: char) -> bool {
1045	    arg.get_short() == Some(flag)
1046	        || arg
1047	            .get_all_short_aliases()
1048	            .is_some_and(|aliases| aliases.contains(&flag))
