1112	/// De-duplicate flag candidates.
1113	///
1114	/// With an empty word every long spelling of an argument (its long name and
1115	/// visible aliases) is offered, while short spellings are still collapsed to
1116	/// the canonical short and dropped for arguments that also have a long form.
1117	/// Once a prefix is typed at most one spelling of an argument can match, so
1118	/// candidates are de-duplicated by argument id as before.
1119	fn dedup_argument_candidates(completions: &mut Vec<CompletionCandidate>, empty_word: bool) {
1120	    if empty_word {
1121	        let long_ids: std::collections::HashSet<String> = completions
1122	            .iter()
1123	            .filter(|candidate| {
1124	                candidate.get_id().is_some() && candidate.get_value().starts_with("--")
1125	            })
1126	            .filter_map(|candidate| candidate.get_id().cloned())
1127	            .collect();
1128	        let mut seen_short_ids = std::collections::HashSet::new();
1129	        completions.retain(|candidate| {
1130	            let Some(id) = candidate.get_id() else {
1131	                return true;
1132	            };
1133	            if candidate.get_value().starts_with("--") {
1134	                // Keep the long name and every visible alias.
1135	                true
1136	            } else if long_ids.contains(id) {
1137	                // Prefer the long forms over the short ones.
1138	                false
1139	            } else {
1140	                seen_short_ids.insert(id.clone())
1141	            }
1142	        });
1143	    } else {
1144	        let mut seen_ids = std::collections::HashSet::new();
1145	        completions.retain(|candidate| {
1146	            if let Some(id) = candidate.get_id().cloned() {
1147	                seen_ids.insert(id)
1148	            } else {
1149	                true
1150	            }
1151	        });
1152	    }
1153	}
