1155	/// Whether `first` and `second` conflict, no matter which one declares it.
1156	fn args_conflict(cmd: &clap::Command, first: &clap::Arg, second: &clap::Arg) -> bool {
1157	    cmd.get_arg_conflicts_with(first)
1158	        .iter()
1159	        .any(|c| c.get_id() == second.get_id())
1160	        || cmd
1161	            .get_arg_conflicts_with(second)
1162	            .iter()
1163	            .any(|c| c.get_id() == first.get_id())
1164	}
