1166	/// The positional the parser would fill at `pos_index`.
1167	///
1168	/// A `last(true)` positional only exists after `--`; before the terminator
1169	/// the parser rejects values for it, so it must not be completed.
1170	fn find_positional(cmd: &clap::Command, pos_index: usize, is_escaped: bool) -> Option<&clap::Arg> {
1171	    cmd.get_positionals()
1172	        .find(|p| p.get_index() == Some(pos_index) && (is_escaped || !p.is_last_set()))
1173	}
