373	    /// [`EnvCompleter::write_complete`] that this generates and actually calling [`EnvCompleter::write_complete`].
374	    /// Caching the results of this call may result in invalid or no completions to be generated.
375	    ///
376	    /// </div>
377	    fn write_registration(
378	        &self,
379	        var: &str,
380	        name: &str,
381	        bin: &str,
382	        completer: &str,
383	        buf: &mut dyn std::io::Write,
384	    ) -> Result<(), std::io::Error>;
