274	/// Position within [`RawArgs`]
275	#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
276	pub struct ArgCursor {
277	    cursor: usize,
278	}
279	
280	impl ArgCursor {
281	    fn new() -> Self {
282	        Self { cursor: 0 }
283	    }
284	}
