        // word count and `arg_index` are unchanged, and the `Command` itself
        // is never mutated, so repeated calls cannot leak one applet's state
        // into another.
        args[0] = OsString::from(applet.get_name());
    }

    let mut raw_args = clap_lex::RawArgs::new(args);
    let mut cursor = raw_args.cursor();
    let mut target_cursor = raw_args.cursor();
    raw_args.seek(
        &mut target_cursor,
        clap_lex::SeekFrom::Start(arg_index as u64),
    );
